var semantics = function (state) {
  return {
    red: ["R1", "R3"].includes(state) ? 1 : 0,
    dress: ["R1", "R2"].includes(state) ? 1 : 0,
    object: 1,
    STOP: 1,
    START: 1,
  };
};

var alpha = 1;

